	// local copy first.
	var localMsgs  = (opts.localMsgs  !== undefined) ? opts.localMsgs  : (b.messages || []);
	var remoteMsgs = (opts.remoteMsgs !== undefined) ? opts.remoteMsgs : (a.messages || []);
